import {createHash,timingSafeEqual} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {allowed,runCommand,bounded,collect} from './admin-bot-core.mjs';
const workSql=readFileSync(new URL('./work-query.sql',import.meta.url),'utf8');
export function secretFor(token){return createHash('sha256').update(`telegram-webhook:${token}`).digest('base64url');}
export function verify(actual,expected){const a=Buffer.from(String(actual??'')),b=Buffer.from(expected);return a.length===b.length&&timingSafeEqual(a,b);}
async function snapshot(pool,signal){const query=async text=>{if(signal.aborted)throw Error();return(await pool.query({text,query_timeout:9000})).rows;};const[accounts,services,mappings,work]=await Promise.all([query('SELECT id,provider_id,name,api_url,api_key,is_active,priority,last_used_at,delivery_multiplier FROM public.provider_accounts WHERE is_active=true'),query('SELECT id,provider_id,provider_service_id,name,min_quantity FROM public.services'),query('SELECT service_id,provider_account_id,provider_service_id,sort_order,is_active FROM public.service_provider_mapping WHERE is_active=true'),query(workSql)]);return{accounts,services,mappings,work};}
export async function getDhanReport(pool){return bounded(async signal=>collect(await snapshot(pool,signal),'plan','Dhansmm',signal));}
export async function dhanWebhook(req,res,pool){const token=process.env.TELEGRAM_BOT_TOKEN;if(!token||!verify(req.headers['x-telegram-bot-api-secret-token'],secretFor(token)))return res.status(401).json({error:'Unauthorized'});const u=req.body??{},m=u.message??u.edited_message,chat=m?.chat?.id;const raw=[process.env.TELEGRAM_ADMIN_CHAT_ID,process.env.TELEGRAM_CHAT_ID].filter(Boolean).join(',');if(!allowed(chat,raw))return res.status(200).json({ok:true,ignored:true});if(!Number.isSafeInteger(u.update_id)||u.update_id<0||typeof m?.text!=='string'||m.text.length>4096)return res.status(400).json({error:'Invalid update'});try{const claim=await pool.query({text:'INSERT INTO public.admin_bot_updates(update_id) VALUES($1) ON CONFLICT DO NOTHING RETURNING update_id',values:[u.update_id],query_timeout:4000});if(!claim.rows.length)return res.json({ok:true,duplicate:true});res.json({ok:true});const send=async(chat_id,text,reply_markup)=>{const response=await fetch(`https://api.telegram.org/bot${token}/sendMessage`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chat_id,text,parse_mode:'HTML',reply_markup,disable_web_page_preview:true}),signal:AbortSignal.timeout(10000)});const data=await response.json();if(!response.ok||!data.ok)throw Error('Telegram delivery unavailable');};await runCommand({text:m.text,chatId:chat,send,snapshot:signal=>snapshot(pool,signal),site:'Dhansmm',url:'https://dhansmm.site/admin/topup-plan'});await pool.query('UPDATE public.admin_bot_updates SET processed_at=now(),status=$2 WHERE update_id=$1',[u.update_id,'processed']);}catch{if(!res.headersSent)res.status(503).json({error:'Bot temporarily unavailable'});console.error('admin-bot processing unavailable');}}
